import type { FantasyVoyageScene, FantasyVoyageChapterDetail } from './fantasy-voyage-scene-types.ts';

export const FANTASY_VOYAGE_LATE_SCENES: FantasyVoyageScene[] = [
  {"chapter":10,"stage":"field","requires":["voyage-09-compare"],"setup":{"ko":"천둥종의 중계 순서에 별길을 겹치자 마지막 방향이 조금 비껴간다. 떠도는섬 관측대에는 별 높이와 계류추의 흔들림이 나란히 적혀 있다.","en":"Laying the starcourse over Stormbell’s relay sequence leaves a small bearing error. Drift Isle’s observation desk records star heights beside the motion of its mooring weight.","ja":"雷鐘の中継順に星路を重ねると、最後の方角が少しずれる。浮島の観測台には星の高さと係留錘の揺れが並べて記されている。"},"approaches":{"observe":{"ko":"별과 계류추 기록 살피기","en":"Survey stars and mooring notes","ja":"星と係留錘の記録を調べる"},"analyze":{"ko":"두 관측 기준 구분하기","en":"Separate the two reference frames","ja":"二つの観測基準を分ける"},"restore":{"ko":"흩어진 관측장 맞추기","en":"Reassemble the observation sheets","ja":"散らばった観測紙を合わせる"}},"success":{"ko":"관측장은 하늘의 방향과 섬 자체의 이동을 따로 적고 있었다. 두 열을 더해 버린 사본이 방향 오차의 한 원인이므로 분리 계산이 필요하다.","en":"The sheets record sky bearings separately from the island’s own drift. A copy that added the two columns explains part of the error, so they must be calculated separately.","ja":"観測紙は空の方角と島自体の移動を別々に記していた。二列を足した写しがずれの一因であり、分けて計算する必要がある。"},"failure":{"ko":"두 열의 시간 표식이 아직 맞지 않아 이동량을 구분할 수 없으니 같은 표식의 장부터 다시 맞춰 보자.","en":"The columns’ time marks do not yet align; match sheets with the same mark before separating their motion.","ja":"二列の時刻印が合わず移動量を分けられないので、同じ印の紙から合わせ直そう。"},"clue":{"name":{"ko":"하늘과 섬의 두 관측열","en":"Two columns for sky and island","ja":"空と島の二つの観測列"},"fact":{"ko":"관측 원본은 별 방향과 섬의 이동을 서로 다른 열에 기록한다.","en":"The original observations keep stellar bearings and island drift in separate columns.","ja":"観測原本は星の方角と島の移動を別の列に記す。"}},"next":{"ko":"같은 시간의 두 열을 맞춰 섬의 이동만 빼야 별 방향을 재검증할 수 있다.","en":"Align both columns at one time and subtract the drift to verify the star bearing.","ja":"同じ時刻の二列を合わせ、島の移動だけを除いて星の方角を再検証しよう。"}},
  {"chapter":10,"stage":"verify","requires":["voyage-10-field"],"setup":{"ko":"분리한 관측열에서 같은 시간 표식을 고를 수 있게 되었다. 사막 별방향판과 소금거울 눈금을 옆에 두고 떠도는섬의 이동분을 지워 보자.","en":"The separated columns now allow observations from one time to be paired. Set the desert star plate and Saltglass scale beside them and remove Drift Isle’s motion.","ja":"分けた観測列から同じ時刻の組を選べるようになった。砂漠の星方位板と塩鏡の目盛りを並べ、浮島の移動分を除こう。"},"approaches":{"observe":{"ko":"고정된 별의 반복값 살피기","en":"Inspect repeated fixed-star readings","ja":"固定星の繰り返す値を見る"},"analyze":{"ko":"섬의 이동분 빼기","en":"Subtract the island’s drift","ja":"島の移動分を引く"},"restore":{"ko":"보정 눈금 틀 맞추기","en":"Align a correction-scale frame","ja":"補正目盛りの枠を合わせる"}},"success":{"ko":"이동분을 뺀 별 방향이 사막 원판과 소금거울 보정값에 함께 맞았다. 서로 다른 장소의 관측이 같은 방향을 가리켜 잃어버린 별길을 독립적으로 확인할 수 있다.","en":"The corrected bearing agrees with both the desert plate and the Saltglass correction. Observations from separate places now point the same way, independently supporting the lost starcourse.","ja":"移動分を除いた方角が砂漠の原板と塩鏡の補正値の両方に合った。別々の場所の観測が同じ向きを示し、失われた星路を独立に裏付けた。"},"failure":{"ko":"고정점 하나를 잘못 잡아 두 눈금이 어긋나니 가장 또렷한 반복 관측부터 계산을 다시 해 보자.","en":"One reference point is misplaced; recalculate from the clearest repeated observation to align the scales.","ja":"固定点を一つ取り違えて目盛りがずれるので、最も明瞭な反復観測から計算し直そう。"},"clue":{"name":{"ko":"이동을 뺀 별 방향","en":"A bearing corrected for drift","ja":"移動を除いた星の方角"},"fact":{"ko":"섬의 이동을 제거한 관측값은 사막 별길과 소금거울 나침반의 보정에 일치한다.","en":"Readings corrected for island drift agree with the desert starcourse and Saltglass compass correction.","ja":"島の移動を除いた観測値は砂漠の星路と塩鏡の羅針盤補正に一致する。"}},"next":{"ko":"리라의 원본 대조본에 이 계산을 옮겨 어느 해석이 재현되는지 확인하자.","en":"Take this calculation to Lyra’s original comparison copy and test which interpretation reproduces it.","ja":"この計算をリラの照合原本へ移し、同じ結果になる読み方を確かめよう。"}},
  {"chapter":10,"stage":"compare","requires":["voyage-10-verify"],"setup":{"ko":"리라는 별읽는탑에서 원본과 선단의 매입 제안서를 따로 펼쳐 둔다. 가져온 독립 관측값을 그녀의 잃어버린 별길 조각에 겹쳐 보자.","en":"At Starspire, Lyra lays out the original and the fleet’s purchase offer separately. Overlay the independent observations on her fragment of the lost starcourse.","ja":"星詠みの塔でリラは原本と船団の買い取り状を別に広げる。持ち帰った独立観測を、失われた星路の断片に重ねよう。"},"approaches":{"observe":{"ko":"원본의 별 표식 대조하기","en":"Compare stars on the original","ja":"原本の星印を比べる"},"analyze":{"ko":"독립 관측의 오차 검산하기","en":"Check independent-reading errors","ja":"独立観測の誤差を検算する"},"restore":{"ko":"분리 보관할 대조본 만들기","en":"Assemble a separate comparison copy","ja":"別に保管する照合本を整える"}},"success":{"ko":"리라의 별길 조각에 보정된 방향이 들어맞았고, 빈 마지막 칸은 조수와 월식 표식으로 표시되어 있었다. 리라는 매입을 거절하고 대조본을 남겨 항로를 독점 문서로 넘기지 않았다.","en":"The corrected bearing fits Lyra’s fragment, whose last empty box is marked with tides and an eclipse. She refuses the purchase and keeps a comparison copy, withholding the route from exclusive ownership.","ja":"補正した方角がリラの断片に合い、最後の空欄には潮と月食の印があった。リラは買い取りを断り照合本を残して、航路を独占の文書に渡さなかった。"},"failure":{"ko":"별 표식의 방향이 뒤집혀 마지막 칸을 읽을 수 없으니 관측장의 위아래를 다시 맞춰 보자.","en":"A star mark is inverted and obscures the last box; realign the top and bottom of the observation sheet.","ja":"星印の向きが逆で最後の欄を読めないので、観測紙の上下を合わせ直そう。"},"clue":{"name":{"ko":"조수 표식이 남은 별길","en":"A starcourse with a tidal blank","ja":"潮の印が残る星路"},"fact":{"ko":"보정된 별길의 마지막 빈칸에는 조수와 월식을 함께 읽으라는 표식이 있다.","en":"The corrected starcourse’s final blank bears a mark for reading tide and eclipse together.","ja":"補正した星路の最後の空欄には潮と月食を共に読む印がある。"}},"next":{"ko":"푸른돛항의 에바에게 거울물결섬의 물빛과 이 조수 표식을 함께 조사해 달라고 부탁하자.","en":"Ask Eva in Verdant Quay to investigate Mirrorwake’s waterlight together with this tidal mark.","ja":"緑帆港のエヴァに、鏡波の水明かりとこの潮の印を共に調べる相談をしよう。"}},
  {"chapter":11,"stage":"field","requires":["voyage-10-compare"],"setup":{"ko":"리라의 별길 마지막 칸에는 조수와 월식의 표식만 남아 있다. 거울물결섬 앞 물빛에는 흰 지붕과 꽃밭 같은 형상이 나타나지만 파도마다 길이가 달라진다.","en":"Only tide and eclipse marks remain in Lyra’s last chart box. Before Mirrorwake, the waterlight resembles white roofs and flower beds, but their lengths change with the waves.","ja":"リラの星路の最後の欄には潮と月食の印だけが残る。鏡波の前の水明かりは白い屋根や花畑に見えるが、波ごとに長さが変わる。"},"approaches":{"observe":{"ko":"같은 해안선 반복 관측하기","en":"Observe one shoreline repeatedly","ja":"同じ海岸線を繰り返し見る"},"analyze":{"ko":"시점에 따른 길이 비교하기","en":"Compare lengths by viewpoint","ja":"視点ごとの長さを比べる"},"restore":{"ko":"해안 관측 표식 세우기","en":"Set up shoreline sight marks","ja":"海岸の観測目印を組む"}},"success":{"ko":"발밑의 해안은 그대로인데 물빛의 지붕은 보는 위치에 따라 옮겨 갔다. 낙원처럼 보이는 형상이 고정된 육지가 아니라는 단서를 얻었으므로 반사각을 따로 재야 한다.","en":"The shore underfoot stays fixed while the luminous roofs shift with the observer. The paradise-like outline is therefore not fixed land, and its reflection angle needs a separate measure.","ja":"足元の海岸は変わらないのに、光の屋根は見る位置で移った。楽園のような形は固定した陸ではないと分かり、反射角を別に測る必要がある。"},"failure":{"ko":"파도가 가라앉기 전 다른 지점을 비교해 변화 원인을 가릴 수 없으니 한 표식을 기준으로 다시 관측하자.","en":"Comparisons were taken from different points before the waves settled; repeat them from a single sight mark.","ja":"波が落ち着く前に別の地点を比べて原因を分けられないので、一つの目印から観測し直そう。"},"clue":{"name":{"ko":"시점에 따라 움직이는 지붕","en":"Roofs that move with the viewpoint","ja":"視点で動く屋根"},"fact":{"ko":"물빛 속 지붕의 위치는 관측 지점에 따라 변하지만 실제 해안은 변하지 않는다.","en":"The luminous roofs move with the viewpoint while the actual shoreline stays fixed.","ja":"水明かりの屋根は観測点で移るが、実際の海岸は変わらない。"}},"next":{"ko":"같은 표식에서 반사각과 조수 눈금을 맞춰 별길의 마지막 칸을 읽을 수 있는지 확인하자.","en":"Align reflection angles and tide readings at the same mark to test the chart’s final box.","ja":"同じ目印で反射角と潮の目盛りを合わせ、星路の最後の欄を読めるか確かめよう。"}},
  {"chapter":11,"stage":"verify","requires":["voyage-11-field"],"setup":{"ko":"시점에 따라 움직이는 형상을 실재 해안과 분리해 기록할 수 있게 되었다. 물가의 계측판에는 조수 눈금 옆에 낡은 월식 관측표가 남아 있다.","en":"The shifting image can now be recorded separately from the real shore. A waterside measuring plate preserves an old eclipse table beside its tidal scale.","ja":"動く像を実際の海岸と分けて記録できるようになった。水辺の計測板には潮の目盛りの隣に古い月食観測表が残る。"},"approaches":{"observe":{"ko":"조수 눈금과 반영 살피기","en":"Inspect tide scales and reflections","ja":"潮の目盛りと反映を見る"},"analyze":{"ko":"월식 기준과 각도 대응하기","en":"Map eclipse references to angles","ja":"月食基準と角度を対応させる"},"restore":{"ko":"기울어진 판독틀 맞추기","en":"Align the tilted reading frame","ja":"傾いた読取枠を合わせる"}},"success":{"ko":"월식 기준으로 맞춘 조수 눈금이 별길 마지막 칸의 표식과 일치했다. 반사된 낙원이 흐려지는 각도에서 실제 항해에 쓸 조수 순서를 읽을 수 있었다.","en":"Tidal readings aligned to the eclipse reference match the last box’s symbol. At the angle where the reflected paradise fades, the usable tidal sequence becomes readable.","ja":"月食基準で合わせた潮の目盛りが最後の欄の印と一致した。反映の楽園が薄れる角度から、実際の航海に使う潮の順を読めた。"},"failure":{"ko":"반사각과 수위 기준을 섞어 순서를 확정할 수 없으니 기준선 하나씩 따로 맞춰 보자.","en":"Reflection and water-level references were mixed; align each baseline separately before concluding the sequence.","ja":"反射角と水位の基準が混ざり順を定められないので、基準線を一つずつ合わせ直そう。"},"clue":{"name":{"ko":"월식 기준의 조수 순서","en":"A tidal sequence on an eclipse reference","ja":"月食基準の潮の順"},"fact":{"ko":"월식표에 맞춘 조수 눈금은 별길의 마지막 표식과 같은 순서를 나타낸다.","en":"Tide readings aligned to the eclipse table reproduce the last starcourse mark’s sequence.","ja":"月食表に合わせた潮の目盛りは星路の最後の印と同じ順を示す。"}},"next":{"ko":"에바에게 반영 관측과 조수 순서를 함께 가져가 네 번째 항법 단서인지 대조하자.","en":"Bring Eva both the reflection observations and tidal sequence to test them as the fourth navigation clue.","ja":"エヴァへ反映の観測と潮の順を持ち帰り、第四の航法の手掛かりとして照合しよう。"}},
  {"chapter":11,"stage":"compare","requires":["voyage-11-verify"],"setup":{"ko":"푸른돛항의 에바는 리라의 빈칸과 물빛 관측 도면을 같은 방향으로 놓는다. 세 항법 단서 뒤에 새 조수 순서를 이어 마지막 연결을 확인하자.","en":"Eva lays Lyra’s blank chart box and the waterlight drawings in the same orientation at Verdant Quay. Add the new tidal sequence after the three known clues and check their final connection.","ja":"緑帆港のエヴァはリラの空欄と水明かりの図を同じ向きに置く。三つの航法の後へ新しい潮の順を繋ぎ、最後の接続を確かめよう。"},"approaches":{"observe":{"ko":"네 표식의 이어짐 대조하기","en":"Compare the four connected marks","ja":"四つの印の繋がりを比べる"},"analyze":{"ko":"조수 순서의 읽는 위치 검산하기","en":"Check where to read the tidal sequence","ja":"潮の順を読む位置を検算する"},"restore":{"ko":"네 단서의 대조 도면 묶기","en":"Assemble a four-clue comparison chart","ja":"四つの手掛かりの照合図を組む"}},"success":{"ko":"동쪽의 조수·월식 순서가 넷째 항법 단서로 이어졌고, 낙원의 형상은 반영이라는 설명과 일치했다. 네 단서가 모였지만 안전하게 통과한 사례를 확인하기 전에는 완성 항로라고 부를 수 없다.","en":"The eastern tide-and-eclipse sequence connects as the fourth clue, while the paradise shape fits the reflection evidence. All four clues are assembled, but a safe passage record is still needed before calling the route complete.","ja":"東方の潮と月食の順が第四の手掛かりとして繋がり、楽園の形は反映の証拠と一致した。四つは揃ったが、安全な通過例を確かめるまでは完成した航路とは呼べない。"},"failure":{"ko":"조수 표식을 반대 방향으로 옮겨 연결이 끊겼으니 관측 도면의 방향부터 다시 맞추자.","en":"The tidal mark was transferred backward and broke the connection; realign the observation drawing first.","ja":"潮の印を逆向きに写して繋がりが切れたので、観測図の向きから合わせ直そう。"},"clue":{"name":{"ko":"모인 네 항법 단서","en":"Four assembled navigation clues","ja":"揃った四つの航法の手掛かり"},"fact":{"ko":"별길·바람 노래·별빛 나침반·조수와 월식의 네 단서가 서로 이어진다.","en":"Starcourse, wind song, starlit compass, and tide-and-eclipse clues connect to each other.","ja":"星路・風の歌・星明かりの羅針盤・潮と月食の四つの手掛かりが繋がる。"}},"next":{"ko":"하스의 미라에게 옛 원정 기록을 찾아 네 단서로도 실패한 이유를 조사해 달라고 부탁하자.","en":"Ask Mira in Hearth to find expedition accounts and investigate why four clues could still fail.","ja":"ハースのミラに古い遠征記を探してもらい、四つの手掛かりでも失敗した理由を調べよう。"}},
  {"chapter":12,"stage":"field","requires":["voyage-11-compare"],"setup":{"ko":"네 항법을 연결했지만 실제 통과를 입증할 기록은 아직 없다. 루네리아의 원정기에는 미라의 편지와 같은 우편 인장과 되돌아온 항적이 보인다.","en":"The four navigation clues are connected, but no record yet proves a successful passage. Mooncity’s expedition account bears the letters’ dispatch seal beside a returning track.","ja":"四つの航法は繋がったが、通過を示す記録はまだない。月都の遠征記にはミラの手紙と同じ差出印と、戻った航跡がある。"},"approaches":{"observe":{"ko":"인장과 항적의 순서 살피기","en":"Inspect seal and track order","ja":"封印と航跡の順を調べる"},"analyze":{"ko":"출항·귀항 기록 나누기","en":"Separate departure and return entries","ja":"出航と帰港の記録を分ける"},"restore":{"ko":"빠진 원정기 장순서 맞추기","en":"Reorder separated expedition pages","ja":"離れた遠征記の頁順を整える"}},"success":{"ko":"같은 우편 인장이 이 원정과 미라의 편지를 연결하며, 원정기는 네 항법을 기록한 뒤 출발점으로 돌아왔다. 출항 방향만의 문제가 아니므로 되돌아오기 직전의 표지를 살펴야 한다.","en":"The matching dispatch seal links this expedition to Mira’s letters, and its log records four clues before a return to the starting point. Departure bearing alone cannot explain the result; the markers just before the turn need inspection.","ja":"同じ差出印が遠征とミラの手紙を結び、遠征記は四つの航法の後に出発点へ戻ったと記す。出航方位だけの問題ではなく、折り返し直前の標を見る必要がある。"},"failure":{"ko":"장순서가 섞여 출항과 귀항을 구별할 수 없으니 연속된 수위 표식부터 맞춰 보자.","en":"The pages mix departure and return; align their consecutive water-level marks before reading the track.","ja":"頁順が混ざって出航と帰港を分けられないので、続く水位印から合わせ直そう。"},"clue":{"name":{"ko":"네 단서를 쓴 실패 원정기","en":"A failed expedition using four clues","ja":"四つの手掛かりを使った失敗の遠征記"},"fact":{"ko":"편지와 같은 인장을 쓴 원정기는 네 항법을 적은 뒤 출발점으로 돌아왔다고 기록한다.","en":"The expedition account with the letters’ seal records four clues followed by a return to its starting point.","ja":"手紙と同じ印の遠征記は、四つの航法の後に出発点へ戻ったと記す。"}},"next":{"ko":"되돌림 직전 장면을 네 단서에 맞춰 재구성하면 누락된 절차를 찾을 수 있다.","en":"Reconstruct the moment before the turn against the four clues to identify the missing procedure.","ja":"折り返す直前を四つの手掛かりで再構成し、抜けた手順を探そう。"}},
  {"chapter":12,"stage":"verify","requires":["voyage-12-field"],"setup":{"ko":"원정기의 네 항법은 지금 모은 단서와 대응한다. 다만 안개 속 그림과 귀환 방향을 적어야 할 두 칸은 비어 있다.","en":"The expedition’s four navigation entries correspond to the recovered clues. Two boxes for mist signs and homeward bearings, however, are empty.","ja":"遠征記の四つの航法は集めた手掛かりと対応する。しかし霧の絵と帰路の方角を記す二欄は空いている。"},"approaches":{"observe":{"ko":"되돌림 직전 여백 살피기","en":"Inspect margins before the turn","ja":"折り返し直前の余白を見る"},"analyze":{"ko":"네 단서와 빠진 절차 대조하기","en":"Compare four clues with omitted steps","ja":"四つの手掛かりと抜けた手順を比べる"},"restore":{"ko":"항적 모형에 빈칸 옮기기","en":"Place the blanks on a track model","ja":"航跡模型に空欄を置く"}},"success":{"ko":"여백에는 보호 안개의 표지를 지나쳤고 귀환 방향도 다시 읽지 않았다는 짧은 메모가 남아 있었다. 네 단서만으로는 통과와 귀환을 보장할 수 없다는 실패 원인이 구체화됐다.","en":"A margin note says the expedition passed the ward-mist signs without reading them and never reread the homeward bearing. The failure now has a concrete gap: four clues alone did not secure passage and return.","ja":"余白には守りの霧の標を読み飛ばし、帰路の方角も読み直さなかったとあった。四つの手掛かりだけでは通過と帰還を保証しない、具体的な欠落が分かった。"},"failure":{"ko":"메모의 화살표를 다른 구간과 연결해 누락 지점을 정하지 못했으니 접힌 모서리를 기준으로 다시 펴 보자.","en":"A note’s arrow was matched to the wrong leg; use the folded corner to restore its position.","ja":"メモの矢印を別区間に結んで欠落箇所を定められないので、折り目を基準に広げ直そう。"},"clue":{"name":{"ko":"읽지 않은 안개 표지와 귀환칸","en":"Unread mist signs and return boxes","ja":"読まなかった霧の標と帰路欄"},"fact":{"ko":"원정기 메모는 보호 안개 표지와 귀환 방향의 확인을 생략했다고 명시한다.","en":"The expedition margin explicitly records omitted checks of ward-mist signs and the homeward bearing.","ja":"遠征記の余白は守りの霧の標と帰路方位の確認を省いたと明記する。"}},"next":{"ko":"미라와 원정기의 끝장을 대조해 편지의 행방 조사와 다음 안개 표지 조사를 이어 보자.","en":"Compare the final pages with Mira to link the letters’ trail to the next mist-sign investigation.","ja":"ミラと遠征記の終わりを比べ、手紙の行方と次の霧の標の調査を繋ごう。"}},
  {"chapter":12,"stage":"compare","requires":["voyage-12-verify"],"setup":{"ko":"미라는 하스에서 원정기의 끝장과 미배달 편지 묶음을 나란히 둔다. 안개 표지와 귀환칸이 빠진 지점을 짚으며 그들이 남긴 증언을 읽어 보자.","en":"In Hearth, Mira places the expedition’s closing pages beside the undelivered letters. Mark the omitted mist and return checks, then read the testimony they left.","ja":"ハースでミラは遠征記の終わりと未配達の手紙を並べる。霧の標と帰路確認の抜けを指し、残された証言を読もう。"},"approaches":{"observe":{"ko":"마지막 증언과 편지 인장 대조하기","en":"Compare final testimony and letter seals","ja":"最後の証言と手紙の印を比べる"},"analyze":{"ko":"실패 순서와 누락 표지 정리하기","en":"Order the failure and missing signs","ja":"失敗の順と抜けた標を整理する"},"restore":{"ko":"다음 조사용 여백 사본 만들기","en":"Reconstruct a margin copy for the next inquiry","ja":"次の調査用の余白の写しを整える"}},"success":{"ko":"원정의 되돌림은 안개 표지와 귀환 절차를 빠뜨린 기록에 일치했고, 끝장에는 옛 해전 때 섬을 숨겼다는 증언이 있었다. 미라는 발신자의 운명을 단정하지 않고 같은 표지 사본이 묵향 서고에 있다는 연결을 찾았다.","en":"The recorded omissions explain the expedition’s turn, while its final page recalls concealment during an old sea war. Mira does not infer the writers’ fate; she finds a lead to copies of the same signs in Inkstone’s archive.","ja":"記録の抜けが遠征の折り返しと一致し、終頁には古い海戦で島を隠したとの証言があった。ミラは書き手の運命を決めつけず、同じ標の写しが墨香にあると見つけた。"},"failure":{"ko":"증언의 시기와 편지 발신 시점을 섞어 읽었으니 같은 날짜라 단정하지 말고 인장의 연결부터 다시 확인하자.","en":"The testimony’s period was confused with the letters’ dispatch; verify the sequence of seals rather than assuming one date.","ja":"証言の時期と手紙の差出時を混同しているので、日付でなく印の連続を確かめ直そう。"},"clue":{"name":{"ko":"전쟁 증언과 묵향의 표지 사본","en":"War testimony and Inkstone sign copies","ja":"海戦の証言と墨香の標の写し"},"fact":{"ko":"원정기 끝장은 옛 해전의 은폐 증언과 묵향에 남은 같은 안개 표지 사본을 연결한다.","en":"The account’s final pages link old sea-war concealment testimony to matching mist-sign copies in Inkstone.","ja":"遠征記の終頁は古い海戦での隠蔽の証言と、墨香に残る同じ霧の標の写しを結ぶ。"}},"next":{"ko":"묵향도시의 시오리에게 안개 표지 사본을 보여 주고 네 문양의 출처를 조사하자.","en":"Show Shiori in Inkstone City the sign copy and investigate the four emblems’ source.","ja":"墨香の街のシオリに霧の標の写しを見せ、四つの紋の出所を調べよう。"}},
  {"chapter":13,"stage":"field","requires":["voyage-12-compare"],"setup":{"ko":"원정기에서 빠뜨린 안개 표지와 시오리의 여백 사본이 같은 네 그림을 품고 있다. 솔바람의 보존 표찰에는 그 그림이 작은 상자들의 작업 순서처럼 반복된다.","en":"The signs omitted by the expedition and Shiori’s margin copy carry the same four drawings. On Pinewatch’s preserved labels, those drawings repeat like the work order of small boxes.","ja":"遠征が読み飛ばした霧の標とシオリの余白の写しには同じ四つの絵がある。松風の保存札では、その絵が小箱の作業順のように繰り返される。"},"approaches":{"observe":{"ko":"표찰의 네 그림 살피기","en":"Inspect the four label drawings","ja":"札の四つの絵を調べる"},"analyze":{"ko":"그림의 반복 위치 세기","en":"Count the repeating positions","ja":"絵が繰り返す位置を数える"},"restore":{"ko":"부서진 표찰 순서 맞추기","en":"Arrange broken labels in order","ja":"割れた札の順を整える"}},"success":{"ko":"새·잎·망치·붓 그림이 표찰마다 같은 간격으로 반복되었다. 장식 문양으로 보기에는 순서가 일정하므로 안개 표지 사본의 읽는 방향과 대조해야 한다.","en":"Bird, leaf, hammer and brush recur at the same intervals on each label. Their order is too regular to dismiss as ornament, so it must be checked against the mist copy’s reading direction.","ja":"鳥・葉・槌・筆が札ごとに同じ間隔で繰り返された。飾りだけと見るには順が一定で、霧の写しの読む向きとの照合が必要だ。"},"failure":{"ko":"깨진 표찰을 거꾸로 놓아 반복을 확인하지 못했으니 모서리 홈이 이어지게 다시 배열하자.","en":"An inverted broken label obscures the repetition; arrange the pieces so their corner notches connect.","ja":"割れた札を逆に置いて繰り返しを確かめられないので、角の溝が繋がるよう並べ直そう。"},"clue":{"name":{"ko":"새·잎·망치·붓의 반복","en":"The bird–leaf–hammer–brush repeat","ja":"鳥・葉・槌・筆の繰り返し"},"fact":{"ko":"보존 표찰에는 새·잎·망치·붓 문양이 같은 간격과 순서로 반복된다.","en":"The preserved labels repeat bird, leaf, hammer and brush in the same order and spacing.","ja":"保存札は鳥・葉・槌・筆を同じ間隔と順で繰り返す。"}},"next":{"ko":"표본뜰의 온전한 표찰로 이 순서의 위아래와 시작점을 검증하자.","en":"Use an intact label in the sample yard to verify the sequence’s orientation and starting point.","ja":"標本の庭の完全な札で、この順の上下と始点を確かめよう。"}},
  {"chapter":13,"stage":"verify","requires":["voyage-13-field"],"setup":{"ko":"반복 순서는 찾았지만 사본의 위아래를 아직 확정하지 못했다. 표본뜰의 온전한 표찰에는 걸쇠 홈과 작업명이 그림 곁에 함께 남아 있다.","en":"The repeated order is known, but the copy’s top and bottom are not yet fixed. An intact yard label preserves a hanging notch and work names beside its drawings.","ja":"繰り返す順は分かったが、写しの上下はまだ定まらない。標本の庭の完全な札には掛け溝と作業名が絵の横に残る。"},"approaches":{"observe":{"ko":"걸쇠 홈과 작업명 살피기","en":"Inspect notch and work names","ja":"掛け溝と作業名を見る"},"analyze":{"ko":"그림과 작업 순서 대응하기","en":"Map drawings to work order","ja":"絵と作業順を対応させる"},"restore":{"ko":"표찰 판독 받침 맞추기","en":"Align the label-reading support","ja":"札の読取台を合わせる"}},"success":{"ko":"걸쇠 홈을 위에 두면 그림은 길잡이·재배·제작·기록의 작업명과 차례로 맞았다. 네 문양의 읽는 방향은 왕실 계보가 아니라 작업표의 배열로 확인할 수 있었다.","en":"With the notch at the top, the drawings align with guiding, growing, crafting and recording. A work-label arrangement, rather than a royal genealogy, establishes their reading direction.","ja":"掛け溝を上にすると、絵は案内・栽培・制作・記録の作業名に順に合った。王家の系譜でなく作業札の並びで、四つの紋を読む向きが定まった。"},"failure":{"ko":"문양 이름만 맞추고 걸쇠 방향을 놓쳤으니 온전한 표찰의 홈부터 다시 대조하자.","en":"The emblem names were matched without the notch orientation; compare the intact label’s notch first.","ja":"紋の名だけ合わせて掛ける向きを見落としたので、完全な札の溝から比べ直そう。"},"clue":{"name":{"ko":"작업표로 읽는 네 문양","en":"Four emblems read as work labels","ja":"作業札として読む四つの紋"},"fact":{"ko":"표찰의 걸쇠 방향에 맞추면 네 문양은 길잡이·재배·제작·기록의 작업명과 일치한다.","en":"With the hanging notch aligned, the four emblems match guiding, growing, crafting and recording.","ja":"札の掛け溝を合わせると四つの紋は案内・栽培・制作・記録に一致する。"}},"next":{"ko":"묵향의 시오리에게 이 판독 방향을 가져가 안개 표지 사본과 순서를 맞춰 보자.","en":"Take this orientation to Shiori in Inkstone and align the mist-marker copy.","ja":"この読む向きを墨香のシオリへ持ち帰り、霧の標の写しを合わせよう。"}},
  {"chapter":13,"stage":"compare","requires":["voyage-13-verify"],"setup":{"ko":"시오리의 여백 사본은 원정기가 놓쳤던 표지의 선을 더 또렷하게 보존한다. 솔바람에서 확정한 걸쇠 방향과 작업 순서로 사본을 읽어 보자.","en":"Shiori’s margin copy preserves the signs missed by the expedition more clearly. Read it using the notch orientation and work order established in Pinewatch.","ja":"シオリの余白の写しは遠征が見落とした標の線をより鮮明に残す。松風で確かめた溝の向きと作業順で写しを読もう。"},"approaches":{"observe":{"ko":"표찰과 여백 선 대조하기","en":"Compare labels and margin strokes","ja":"札と余白の線を比べる"},"analyze":{"ko":"네 문양의 회전 순서 풀기","en":"Decode the four emblems’ rotations","ja":"四つの紋の回転順を解く"},"restore":{"ko":"순서대로 여백 사본 펼치기","en":"Lay the margin copies in sequence","ja":"余白の写しを順に広げる"}},"success":{"ko":"안개 표지 사본도 새·잎·망치·붓의 작업 순서로 읽혔다. 다만 문양 곁의 물결 홈이 어느 때 나타나는 표지인지 구별하므로 출현 시각에 대한 관측이 더 필요하다.","en":"The mist copy reads in the same bird, leaf, hammer and brush work order. Wave notches beside the emblems distinguish when signs appear, so their timing still needs observation.","ja":"霧の写しも鳥・葉・槌・筆の作業順で読めた。ただし横の波形の溝が標の現れる時を分けており、出現時刻の観測が更に要る。"},"failure":{"ko":"물결 홈을 글자 획에 섞어 순서를 확정하지 못했으니 문양과 홈을 따로 옮겨 보자.","en":"Wave notches were mixed into letter strokes; copy emblems and notches separately before ordering them.","ja":"波形の溝を文字線に混ぜて順を定められないので、紋と溝を別々に写そう。"},"clue":{"name":{"ko":"작업 순서와 물결 홈","en":"Work order and wave notches","ja":"作業順と波形の溝"},"fact":{"ko":"안개 표지 사본은 네 작업 문양과 출현 때를 구별하는 물결 홈을 함께 가진다.","en":"The mist-sign copy pairs four work emblems with wave notches distinguishing their appearance times.","ja":"霧の標の写しは四つの作業紋と出現時を分ける波形の溝を併せ持つ。"}},"next":{"ko":"솔바람의 미르은에게 물결 홈을 보여 주고 갈대나루의 안개·수위 기록과 연결하자.","en":"Show the wave notches to Mireun in Pinewatch and connect them to Reedcross’s mist and water records.","ja":"松風のミルンに波形の溝を見せ、葦渡りの霧と水位の記録へ繋げよう。"}},
  {"chapter":14,"stage":"field","requires":["voyage-13-compare"],"setup":{"ko":"물결 홈은 문양의 순서뿐 아니라 드러나는 때를 뜻한다. 갈대나루의 누적 관측장에는 갈대 부표 그림과 여러 새벽의 수위·풍향이 함께 적혀 있다.","en":"The wave notches encode when the emblems appear as well as their order. Reedcross’s accumulated observations pair reed-float sketches with water levels and winds from many dawns.","ja":"波形の溝は紋の順だけでなく現れる時も示す。葦渡りの蓄積した観測帳には、葦の浮標と幾度もの夜明けの水位・風向が並ぶ。"},"approaches":{"observe":{"ko":"여러 새벽의 부표 그림 살피기","en":"Inspect floats across several dawns","ja":"複数の夜明けの浮標図を見る"},"analyze":{"ko":"수위와 풍향 열 나누기","en":"Separate water-level and wind columns","ja":"水位と風向の列を分ける"},"restore":{"ko":"관측장과 부표 높이 맞추기","en":"Align the notes with float heights","ja":"観測帳と浮標の高さを合わせる"}},"success":{"ko":"서로 다른 날짜에도 물결 홈은 같은 수위와 풍향 순서에서 드러났다. 날짜보다 바람과 조수의 관계를 따라 읽어야 한다는 비교 근거를 얻었다.","en":"The wave notches appear at the same water-level and wind sequence on different dates. Their readable pattern follows wind and tide relationships rather than a calendar date.","ja":"別の日付でも、波形の溝は同じ水位と風向の順で現れた。暦の日付より風と潮の関係に沿って読む根拠を得た。"},"failure":{"ko":"다른 높이의 부표를 한 표에 섞어 반복 조건을 가릴 수 없으니 같은 갈대 눈금끼리 다시 비교하자.","en":"Floats of different heights were combined; compare matching reed scales to isolate repeated conditions.","ja":"高さの違う浮標を一表に混ぜて条件を分けられないので、同じ葦の目盛り同士を比べ直そう。"},"clue":{"name":{"ko":"날짜가 달라도 반복되는 조건","en":"Conditions repeated across different dates","ja":"日付を越えて繰り返す条件"},"fact":{"ko":"안개 표지의 물결 홈은 여러 날짜에서 같은 수위·풍향 순서에 드러났다.","en":"Mist-sign notches appeared on different dates in the same water-level and wind sequence.","ja":"霧の標の溝は複数の日付で同じ水位・風向の順に現れた。"}},"next":{"ko":"같은 높이의 부표로 문양의 출현 순서와 조수 간격이 일치하는지 검증하자.","en":"Use equal-height floats to verify the emblems’ order against tidal intervals.","ja":"同じ高さの浮標で、紋の出現順と潮の間隔が合うか確かめよう。"}},
  {"chapter":14,"stage":"verify","requires":["voyage-14-field"],"setup":{"ko":"같은 조건의 관측장만 모아 날짜 차이를 분리했다. 물결 홈의 수와 갈대 부표에서 드러나는 네 문양을 한 줄로 맞춰 보자.","en":"Observations under matching conditions have been separated from their date differences. Align the wave-notch counts with the four emblems appearing on the reed floats.","ja":"同じ条件の観測帳を集め、日付の違いを分けた。波形の溝の数と葦の浮標に現れる四つの紋を一列に合わせよう。"},"approaches":{"observe":{"ko":"네 문양 출현 순서 살피기","en":"Observe the emblems’ appearance order","ja":"四つの紋の出現順を見る"},"analyze":{"ko":"조수 간격과 홈 개수 대응하기","en":"Match tidal intervals to notch counts","ja":"潮の間隔と溝の数を対応させる"},"restore":{"ko":"부표 판독줄 높이 맞추기","en":"Align a float-reading cord","ja":"浮標の読取紐の高さを合わせる"}},"success":{"ko":"바람이 돌아선 뒤 조수가 빠질 때 새·잎·망치·붓 표지가 차례로 드러나는 간격이 홈 수와 맞았다. 안개 회랑의 열림을 일정 날짜가 아니라 이 조건의 반복으로 계산할 수 있다.","en":"As wind turns and tide ebbs, the bird, leaf, hammer and brush appear at intervals matching the notches. The mist corridor can be read through recurring conditions rather than one fixed date.","ja":"風が変わって潮が引くと、鳥・葉・槌・筆が溝の数に合う間隔で順に現れた。霧の回廊は固定日でなく、この条件の繰り返しから読める。"},"failure":{"ko":"바람이 바뀌기 전 기록을 뒤 구간에 넣었으니 풍향 전환점을 기준으로 관측열을 다시 맞추자.","en":"A pre-turn wind record was placed too late; realign the observations at the wind-change point.","ja":"風が変わる前の記録を後へ入れたので、風向の転換点を基準に観測列を合わせ直そう。"},"clue":{"name":{"ko":"바람 전환 뒤의 표지 간격","en":"Marker intervals after the wind turns","ja":"風向転換後の標の間隔"},"fact":{"ko":"바람 전환과 썰물에 나타난 네 문양의 간격은 물결 홈의 수와 일치한다.","en":"The four emblems’ intervals after the wind turns and tide ebbs match the wave-notch counts.","ja":"風向転換と引き潮で現れる四紋の間隔は波形の溝の数に一致する。"}},"next":{"ko":"미르은과 표찰 사본을 대조해 항해 때마다 다시 읽을 조건표로 정리하자.","en":"Compare the label copies with Mireun and compile a conditions table to reread for each voyage.","ja":"ミルンと札の写しを比べ、航海のたびに読み直す条件表へまとめよう。"}},
  {"chapter":14,"stage":"compare","requires":["voyage-14-verify"],"setup":{"ko":"미르은은 솔바람의 표찰과 갈대나루 관측값을 같은 높이 기준으로 펼친다. 표지가 보이는 조건을 적되 특정 날짜만 정답으로 남기지 않도록 대조하자.","en":"Mireun lays Pinewatch’s labels and Reedcross’s readings on one height reference. Record visibility conditions without presenting a single date as the only answer.","ja":"ミルンは松風の札と葦渡りの観測値を同じ高さの基準で広げる。標が見える条件を記し、特定日だけを正解にしないよう照合しよう。"},"approaches":{"observe":{"ko":"조건이 같은 기록끼리 대조하기","en":"Compare records under matching conditions","ja":"同じ条件の記録同士を比べる"},"analyze":{"ko":"출항 조건의 계산 순서 정리하기","en":"Order the departure-condition calculation","ja":"出航条件の計算順を整理する"},"restore":{"ko":"반복해 쓸 조건표 짜기","en":"Assemble a reusable conditions table","ja":"繰り返し使う条件表を組む"}},"success":{"ko":"표찰의 읽는 순서와 부표의 출현 조건이 하나의 표로 맞춰졌다. 미르은은 출항 때 바람과 조수를 새로 확인할 기준을 남겼지만 돌아오는 순서는 아직 이 표만으로 알 수 없다.","en":"Label order and float-appearance conditions now fit one table. Mireun records how to reread wind and tide at departure, but this table alone does not give the return sequence.","ja":"札の読む順と浮標の出現条件が一つの表に揃った。ミルンは出航時に風と潮を読み直す基準を残したが、帰路の順はこの表だけでは分からない。"},"failure":{"ko":"물결 홈의 시작점을 빠뜨려 조건표를 확정하지 못했으니 첫 문양의 높이부터 다시 대조하자.","en":"The starting notch was omitted; compare the first emblem’s height before completing the table.","ja":"波形の溝の始点を落として表を定められないので、最初の紋の高さから比べ直そう。"},"clue":{"name":{"ko":"다시 읽을 수 있는 안개 조건표","en":"A mist-conditions table to reread","ja":"読み直せる霧の条件表"},"fact":{"ko":"표찰 순서와 부표 관측은 출항 때의 풍향·조수를 다시 확인하는 안개 통과 조건표로 연결된다.","en":"Label order and float observations form a mist-passage table that requires fresh wind and tide readings at departure.","ja":"札の順と浮標観測は、出航時の風と潮を読み直す霧の通過条件表へ繋がる。"}},"next":{"ko":"수관도시의 하린에게 조건표를 보여 주고 이끼샘의 귀환 매듭을 조사하자.","en":"Show Harin in Canopy Hall the table and investigate Mossbrook’s return knots.","ja":"樹冠の街のハリンに条件表を見せ、苔泉の帰路の結びを調べよう。"}},
  {"chapter":15,"stage":"field","requires":["voyage-14-compare"],"setup":{"ko":"안개 조건표는 들어갈 때의 표지를 읽지만 돌아올 때의 방향은 말해 주지 않는다. 이끼샘 수로의 매듭에는 양방향 화살표 대신 서로 다른 시작 홈이 새겨져 있다.","en":"The mist table reads inward signs but does not specify the homeward bearing. Mossbrook’s channel knots have different starting notches instead of a simple two-way arrow.","ja":"霧の条件表は入る標を読むが、帰る方角は示さない。苔泉の水路の結びには双方向の矢印でなく、異なる始めの溝が刻まれている。"},"approaches":{"observe":{"ko":"매듭 홈과 물 흐름 살피기","en":"Inspect knot notches and flow","ja":"結びの溝と水の流れを見る"},"analyze":{"ko":"들어감·돌아감 시작점 구분하기","en":"Separate inward and homeward starts","ja":"往路と帰路の始点を分ける"},"restore":{"ko":"흩어진 수로 매듭판 맞추기","en":"Arrange the channel-knot boards","ja":"水路の結び板を合わせる"}},"success":{"ko":"귀환 쪽 홈은 들어갈 때 끝난 자리와 다른 물높이에서 시작했다. 같은 순서를 거꾸로 읽기보다 바뀐 흐름을 새로 읽는 절차라는 근거가 생겼다.","en":"The homeward notch starts at a different water level from the end of the inward leg. This indicates a new reading of changed flow rather than a reversal of the same sequence.","ja":"帰路の溝は往路の終点と違う水位から始まった。同じ順を逆にするのでなく、変わった流れを読み直す手順だと分かった。"},"failure":{"ko":"상류와 하류의 매듭판을 섞어 시작점을 구별하지 못했으니 물높이 홈부터 다시 정렬하자.","en":"Upstream and downstream boards were mixed; align their water-level notches to distinguish the starts.","ja":"上流と下流の板を混ぜて始点を分けられないので、水位の溝から並べ直そう。"},"clue":{"name":{"ko":"귀환의 다른 시작 홈","en":"A different homeward starting notch","ja":"帰路の異なる始めの溝"},"fact":{"ko":"귀환 매듭은 왕복 순서를 뒤집지 않고 다른 물높이의 시작 홈을 둔다.","en":"The return knots use a different water-level starting notch rather than reversing a round trip.","ja":"帰路の結びは往復の順を逆にせず、別の水位の始点を置く。"}},"next":{"ko":"현장의 물길 모형에 두 시작점을 옮겨 귀환 순서가 재현되는지 검증하자.","en":"Transfer both starts to the site’s flow model and test whether the return sequence can be reproduced.","ja":"現地の水路模型へ二つの始点を移し、帰路の順が再現できるか確かめよう。"}},
  {"chapter":15,"stage":"verify","requires":["voyage-15-field"],"setup":{"ko":"귀환 매듭의 시작점을 구분해 물길 모형에 옮길 수 있게 되었다. 작업대의 작은 수로에서 흐름이 바뀔 때 어느 홈이 먼저 드러나는지 맞춰 보자.","en":"The distinct return-knot starts can now be transferred to the flow model. On the workbench’s small channels, match which notch emerges first when the flow changes.","ja":"帰路の結びの始点を分け、水路模型へ移せるようになった。作業台の小水路で流れが変わる時、どの溝が先に現れるか合わせよう。"},"approaches":{"observe":{"ko":"모형의 물높이 변화 살피기","en":"Observe model water-level changes","ja":"模型の水位変化を見る"},"analyze":{"ko":"귀환 순서와 바람 박자 대조하기","en":"Compare return order and wind rhythm","ja":"帰路の順と風の拍子を比べる"},"restore":{"ko":"수로 모형의 판자 맞추기","en":"Align the flow model’s boards","ja":"水路模型の板を合わせる"}},"success":{"ko":"새 물높이에서 바람 노래의 기다림을 적용하자 귀환 홈이 육지 쪽 별길로 이어졌다. 들어갈 때와 다른 흐름을 읽으면 돌아올 방향을 재현할 수 있다는 검증을 얻었다.","en":"Applying the wind song’s pause at the new water level connects the return notch to the landward starcourse. Reading the changed flow reproduces a homeward bearing distinct from the inward sequence.","ja":"新しい水位で風の歌の休みを当てると、帰路の溝が陸への星路に繋がった。往路と違う流れを読めば帰る方角を再現できた。"},"failure":{"ko":"판자 하나가 뒤집혀 흐름이 먼저 갈라지니 홈의 방향을 맞춘 뒤 같은 순서를 다시 시험하자.","en":"One board is reversed and splits the flow too early; align its notch and retest the same sequence.","ja":"板一枚が逆で流れが早く分かれるので、溝の向きを合わせて同じ順を試し直そう。"},"clue":{"name":{"ko":"육지 쪽 별길로 이어진 모형","en":"A model joining the landward starcourse","ja":"陸への星路に繋がる模型"},"fact":{"ko":"바뀐 수위와 바람의 기다림을 적용한 모형은 귀환 홈을 육지 쪽 별길에 연결한다.","en":"A model using the changed water level and wind pause connects the return notch to the landward starcourse.","ja":"変わった水位と風の休みを用いた模型は、帰路の溝を陸への星路へ繋ぐ。"}},"next":{"ko":"하린의 직물표와 모형의 결과를 대조해 귀환 절차를 항법 기록에 넣자.","en":"Compare the model result with Harin’s woven table and incorporate the return procedure into the navigation record.","ja":"ハリンの織り表と模型の結果を比べ、帰還手順を航法の記録へ入れよう。"}},
  {"chapter":15,"stage":"compare","requires":["voyage-15-verify"],"setup":{"ko":"하린은 수관도시의 직물표에서 귀환 매듭이 놓인 가장자리를 펴 보인다. 안개 조건표와 물길 모형의 결과를 그 가장자리부터 읽어 보자.","en":"In Canopy Hall, Harin unfolds the edge of the woven table bearing return knots. Read the mist table and flow-model result from that edge.","ja":"樹冠の街でハリンは帰路の結びがある織り表の端を広げる。霧の条件表と水路模型の結果を、その端から読もう。"},"approaches":{"observe":{"ko":"직물 가장자리와 귀환 홈 대조하기","en":"Compare the woven edge and return notches","ja":"布の端と帰路の溝を比べる"},"analyze":{"ko":"출항·귀환 기준 차이 정리하기","en":"Separate departure and return references","ja":"出航と帰路の基準差を整理する"},"restore":{"ko":"왕복 항법 대조본 엮기","en":"Assemble a two-way navigation copy","ja":"往復の航法の照合本を綴じる"}},"success":{"ko":"직물표는 바뀐 바람과 조수를 새로 읽어야 한다는 모형 결과를 뒷받침했다. 이제 들어갈 길과 돌아올 방법을 분리해 적을 수 있어 귀환 표시가 없는 사본의 결손도 알아볼 수 있다.","en":"The woven table supports the model’s requirement to reread changed wind and tide. Inward and homeward methods can now be recorded separately, making copies without return marks recognizable as incomplete.","ja":"織り表は変わった風と潮を読み直す模型の結果を裏付けた。往路と帰路を分けて記せるようになり、帰路標のない写しの欠落も見分けられる。"},"failure":{"ko":"가장자리의 귀환 홈을 본문의 출항줄에 섞었으니 두 줄을 나눠 다시 엮어 보자.","en":"Return notches on the edge were mixed into the departure line; separate both lines and assemble the copy again.","ja":"端の帰路の溝を本文の出航列へ混ぜたので、二列を分けて綴じ直そう。"},"clue":{"name":{"ko":"분리한 왕복 항법 기록","en":"Separate inward and homeward methods","ja":"分けた往路と帰路の航法記録"},"fact":{"ko":"직물표와 모형은 출항 때와 달라진 바람·조수를 다시 읽는 귀환 절차에 일치한다.","en":"The woven table and model agree on a return procedure that rereads wind and tide changed since departure.","ja":"織り表と模型は出航後に変わった風と潮を読み直す帰還手順で一致する。"}},"next":{"ko":"이끼샘의 솔란에게 왕복 대조본을 전하고 잎그늘에 남은 선단 해도의 결손을 조사하자.","en":"Take the two-way copy to Solan in Mossbrook and investigate gaps in the fleet chart left in Leafshade.","ja":"苔泉のソランに往復の照合本を渡し、葉陰に残る船団の海図の欠落を調べよう。"}},
  {"chapter":16,"stage":"field","requires":["voyage-15-compare"],"setup":{"ko":"귀환 매듭을 구별하게 되자 솔란은 잎그늘의 화물표와 대조할 수 있다고 알려 왔다. 하역장에 남은 해도와 화물표에는 철가면 문양과 같은 짐 번호가 보인다.","en":"With the return knots distinguished, Solan points to cargo records in Leafshade for comparison. A chart and slip left at the unloading yard carry the iron-mask mark and matching cargo numbers.","ja":"帰路の結びを分けられると、ソランは葉陰の荷札と比べられると知らせた。荷下ろし場に残る海図と札には鉄仮面印と同じ荷番号がある。"},"approaches":{"observe":{"ko":"짐 번호와 해도 모서리 살피기","en":"Inspect cargo numbers and chart edges","ja":"荷番号と海図の端を見る"},"analyze":{"ko":"반출 목록과 사본 범위 대조하기","en":"Compare dispatch lists and copy coverage","ja":"搬出一覧と写しの範囲を比べる"},"restore":{"ko":"찢긴 화물표 이어 맞추기","en":"Reassemble the torn cargo slip","ja":"破れた荷札を繋ぐ"}},"success":{"ko":"반출 목록의 짐 번호가 해도 모서리와 맞아 선단이 가져간 사본의 범위를 확인했다. 그 범위에는 앞서 완성한 귀환 표지 칸이 없어 어떤 자료가 빠졌는지 검증할 수 있다.","en":"The dispatch number matches the chart edge and establishes the scope of the copy the fleet seized. It excludes the return-mark box just recovered, giving a specific omission to verify.","ja":"搬出一覧の番号が海図の端と合い、船団が奪った写しの範囲が分かった。完成させた帰路標の欄がなく、欠けた資料を具体的に検証できる。"},"failure":{"ko":"서로 다른 짐 번호의 조각을 이었으니 모서리의 연속된 절취선을 기준으로 다시 맞추자.","en":"Fragments from different cargo numbers were joined; use the continuous tear line at the edge to match them again.","ja":"違う荷番号の断片を繋いだので、端の続く切り取り線を基準に合わせ直そう。"},"clue":{"name":{"ko":"선단 사본의 반출 범위","en":"The fleet copy’s dispatch coverage","ja":"船団の写しの搬出範囲"},"fact":{"ko":"화물표와 모서리 번호가 일치하는 선단 사본에는 귀환 표지 칸이 없다.","en":"The fleet copy matching the slip and edge numbers lacks the return-mark box.","ja":"荷札と端の番号が一致する船団の写しには帰路標の欄がない。"}},"next":{"ko":"빠진 귀환 표지와 안개 회항 기록을 대조하고 선단 독점장의 인장도 검증하자.","en":"Check the missing return marks against the mist-return account and inspect the fleet’s ownership seal.","ja":"欠けた帰路標と霧の帰航記録を比べ、船団の独占状の印も確かめよう。"}},
  {"chapter":16,"stage":"verify","requires":["voyage-16-field"],"setup":{"ko":"선단이 빼앗은 사본은 귀환칸 이전에서 끝난다. 함께 남은 독점장과 옛 회항 기록을 대조하면 불완전한 지도와 실제 소유 권리를 구별할 수 있다.","en":"The seized copy ends before the return box. Comparing the ownership deed left with it and the old turnback account can distinguish an incomplete chart from a legitimate claim.","ja":"奪われた写しは帰路欄の前で終わる。同じ場所に残る独占状と古い帰航記録を比べれば、不完全な地図と正当な権利を分けられる。"},"approaches":{"observe":{"ko":"귀환칸·회항 주석·인장 살피기","en":"Inspect return box, turnback note and seal","ja":"帰路欄・帰航の注記・印を見る"},"analyze":{"ko":"사본과 정본 표찰의 차이 찾기","en":"Compare copy and authentic label marks","ja":"写しと真本の札の違いを探す"},"restore":{"ko":"흐린 인장의 대조 탁본 맞추기","en":"Align comparison rubbings of the faded seal","ja":"薄い印の照合拓本を合わせる"}},"success":{"ko":"사본은 귀환 매듭을 빠뜨렸으며 옛 주석은 표지를 읽지 못한 배를 안전한 외해로 되돌린다고 적고 있었다. 독점장의 인장도 기존 작업 표찰과 달라, 지도 확보가 정당한 소유를 뜻하지 않으며 서명 검증이 필요하다.","en":"The copy omits the return knots, while the old note says unread ships are sent back to safe outer waters. Its ownership seal also differs from the work labels, so possession of a chart cannot establish ownership and its signatures need checking.","ja":"写しは帰路の結びを欠き、古い注記は標を読めない船を安全な外海へ戻すと記していた。独占状の印も作業札と違い、海図を持つだけでは所有の証にならず署名の検証が要る。"},"failure":{"ko":"인장의 얼룩을 작업 문양으로 읽어 비교가 흐려졌으니 번진 부분과 남은 선을 나눠 다시 살피자.","en":"A stain was read as part of the work emblem; separate the blurred patch from surviving lines before comparing.","ja":"印の染みを作業紋と読んで比較が曖昧なので、滲みと残る線を分けて見直そう。"},"clue":{"name":{"ko":"회항 주석과 다른 독점장 인장","en":"A turnback note and mismatched ownership seal","ja":"帰航注記と異なる独占状の印"},"fact":{"ko":"회항 기록은 미해독 배를 안전한 외해로 돌려보낸다고 적으며 독점장 인장은 작업 표찰과 일치하지 않는다.","en":"The turnback note sends unread ships to safe outer waters, and the deed’s seal does not match the work labels.","ja":"帰航注記は読めない船を安全な外海へ戻すと記し、独占状の印は作業札と一致しない。"}},"next":{"ko":"솔란과 네 대륙의 사본 보관 장부를 대조해 선단 밖에도 진본의 근거가 남았는지 확인하자.","en":"Compare the four continents’ copy ledgers with Solan to establish whether authentic sources survive outside the fleet.","ja":"ソランと四大陸の写しの保管帳を比べ、船団の外にも真本の根拠が残るか確かめよう。"}},
  {"chapter":16,"stage":"compare","requires":["voyage-16-verify"],"setup":{"ko":"솔란은 이끼샘에서 서로 다른 대륙의 운송표와 보관 인장을 펼친다. 잎그늘의 반출 범위를 빼고도 어느 대조본이 남았는지 확인하자.","en":"In Mossbrook, Solan lays out transport slips and custody seals from different continents. Check which comparison copies survive outside the Leafshade dispatch.","ja":"苔泉でソランは異なる大陸の運送札と保管印を広げる。葉陰の搬出分を除いても、どの照合本が残るか確かめよう。"},"approaches":{"observe":{"ko":"대륙별 보관 인장 대조하기","en":"Compare continental custody seals","ja":"大陸ごとの保管印を比べる"},"analyze":{"ko":"나뉜 사본의 겹치는 구간 찾기","en":"Find overlaps in the separate copies","ja":"分かれた写しの重なる区間を探す"},"restore":{"ko":"공동 대조본의 목차 엮기","en":"Assemble an index of shared copies","ja":"共同照合本の目次を綴じる"}},"success":{"ko":"별길·관측·직물표·운송 기록의 보관 인장이 각각 남아 네 대륙이 진본을 나눠 지켰음을 확인했다. 독점장에 적힌 창립 권한은 이 협력 기록만으로 인정할 수 없으므로 원래 서명과 의도를 찾아야 한다.","en":"Custody seals survive for starcourse, observations, woven tables and transport records, confirming authentic copies across four continents. These cooperation records do not validate the deed’s claimed founding authority, so original signatures and intent must be traced.","ja":"星路・観測・織り表・運送記録の保管印が残り、四大陸が真本を分けて守ったと確認した。独占状の創設権限はこの協力記録だけでは認められず、元の署名と意図を追う必要がある。"},"failure":{"ko":"같은 사본의 운송표를 서로 다른 진본으로 세었으니 보관 인장의 출처를 기준으로 다시 나누자.","en":"Two slips for one copy were counted as separate originals; distinguish them by their custody-seal origins.","ja":"同じ写しの運送札を二つの真本と数えているので、保管印の出所から分け直そう。"},"clue":{"name":{"ko":"네 대륙에 남은 진본 대조망","en":"An authentic comparison trail across four continents","ja":"四大陸に残る真本の照合網"},"fact":{"ko":"별길·관측·직물표·운송 장부의 서로 다른 보관 인장은 진본을 나누어 지킨 협력 경로를 입증한다.","en":"Distinct seals on starcourse, observation, weaving and transport ledgers establish a distributed trail of authentic custody.","ja":"星路・観測・織り・運送の帳簿の異なる保管印が、真本を分けて守った協力の経路を示す。"}},"next":{"ko":"햇실도시의 줄레에게 보관 인장을 보여 주고 샘쉼의 창립 서명과 연결하자.","en":"Show Zuleh in Sunloom the custody seals and connect them to the founding signatures in Wellrest.","ja":"陽織の街のズレに保管印を見せ、泉憩いの創設の署名へ繋げよう。"}},
  {"chapter":17,"stage":"field","requires":["voyage-16-compare"],"setup":{"ko":"네 대륙의 보관 인장은 샘쉼의 오래된 수령표 네 묶음으로 이어진다. 창립 편지 사본의 서명 일부는 물에 번졌지만 각 묶음의 작업 그림과 출발지 표시는 남아 있다.","en":"The four continents’ custody seals lead to four bundles of old Wellrest receipts. Water has blurred parts of the founding-letter signatures, but the work drawings and dispatch origins remain.","ja":"四大陸の保管印は泉憩いの古い受取札四束へ繋がる。創設の手紙の署名は一部滲むが、束ごとの作業図と出発地は残る。"},"approaches":{"observe":{"ko":"수령표의 작업 그림 살피기","en":"Inspect receipt work drawings","ja":"受取札の作業図を見る"},"analyze":{"ko":"네 묶음의 출발지 구분하기","en":"Separate the four dispatch origins","ja":"四束の出発地を分ける"},"restore":{"ko":"편지와 수령표 가장자리 맞추기","en":"Match letter and receipt edges","ja":"手紙と受取札の端を合わせる"}},"success":{"ko":"네 묶음은 각각 항해·재배·제작·기록 작업과 서로 다른 대륙의 발송지를 기록했다. 창립 편지의 서명을 같은 작업 문양과 짝지을 수 있어 한 사람의 이름을 여러 역할에 잘못 붙이는 일을 피할 수 있다.","en":"Each bundle records navigation, growing, craft or writing and a different continental dispatch point. Their work emblems can pair the letter signatures without assigning one person’s name to several roles.","ja":"四束は航海・栽培・制作・記録の仕事と、それぞれ別の大陸の発送地を記していた。作業紋で手紙の署名を組にでき、一人の名を複数の役へ誤って結ばずに済む。"},"failure":{"ko":"봉투의 접힌 방향을 잘못 읽어 발송지 두 곳이 섞였으니 가장자리 봉인선부터 다시 맞추자.","en":"A folded envelope reversed two dispatch origins; realign the edge seal before pairing them.","ja":"封筒の折る向きを誤って発送地を二つ混ぜたので、端の封印線から合わせ直そう。"},"clue":{"name":{"ko":"네 작업과 네 발송지의 수령표","en":"Receipts for four tasks and four origins","ja":"四つの仕事と発送地の受取札"},"fact":{"ko":"수령표 네 묶음은 항해·재배·제작·기록과 서로 다른 대륙의 발송지를 구분한다.","en":"Four receipt bundles distinguish navigation, growing, craft and writing with separate continental origins.","ja":"四束の受取札は航海・栽培・制作・記録と別々の大陸の発送地を分ける。"}},"next":{"ko":"작업 문양에 맞춘 서명을 반복 필적과 대조해 네 인물의 이름을 검증하자.","en":"Pair the signatures by work emblem and compare repeated handwriting to establish the four names.","ja":"作業紋で組にした署名を繰り返す筆跡と比べ、四人の名を確かめよう。"}},
  {"chapter":17,"stage":"verify","requires":["voyage-17-field"],"setup":{"ko":"작업과 발송지로 나눈 네 묶음에 반복 서명이 남아 있다. 흐려진 한 글자를 추측하기보다 다른 수령표의 같은 필획과 인장을 맞춰 보자.","en":"The bundles separated by work and origin preserve repeated signatures. Instead of guessing a blurred letter, compare matching strokes and seals on other receipts.","ja":"仕事と発送地で分けた四束には署名が繰り返される。滲んだ一字を推測せず、別の受取札の同じ筆画と印を合わせよう。"},"approaches":{"observe":{"ko":"반복 서명의 남은 획 살피기","en":"Inspect surviving repeated strokes","ja":"繰り返す署名の残る画を見る"},"analyze":{"ko":"필적·작업·발송지 교차 대조하기","en":"Cross-check hand, work and origin","ja":"筆跡・仕事・発送地を突き合わせる"},"restore":{"ko":"흐린 이름의 대조 사본 맞추기","en":"Align copies of the faded names","ja":"薄い名の照合写しを合わせる"}},"success":{"ko":"서명은 아우렐리아 항해사 아렌, 실바라 정원사 세린, 카자란 장인 바토, 노크티스 기록사 유안의 이름과 맞았다. 각자의 작업표와 발송지가 반복 확인되어 네 인물을 신분 전설이 아닌 실제 협력자로 구분할 수 있다.","en":"The signatures identify Aren the Aurelian navigator, Serin the Sylvaran gardener, Bato the Kazaran artisan and Yuan the Noctis scribe. Repeated work and origin entries establish four actual collaborators rather than a legend of rank.","ja":"署名はアウレリアの航海者アレン、シルヴァラの庭師セリン、カザランの職人バト、ノクティスの記録士ユアンに合った。仕事と発送地も繰り返し確かめられ、身分の伝説でなく実在の協力者四人を分けられた。"},"failure":{"ko":"이름이 닮은 두 서명을 한 필적으로 묶었으니 작업 인장이 같은 기록끼리 다시 대조하자.","en":"Two similar names were treated as one hand; compare records bearing the same work seal instead.","ja":"似た二つの名を一人の筆跡としたので、同じ作業印の記録同士で比べ直そう。"},"clue":{"name":{"ko":"이름과 일이 맞는 네 협력자","en":"Four collaborators matched to their work","ja":"名と仕事が合う四人の協力者"},"fact":{"ko":"반복 서명·작업표·발송지는 아렌·세린·바토·유안의 이름과 네 대륙에서의 직무를 확인한다.","en":"Repeated signatures, work labels and origins confirm Aren, Serin, Bato and Yuan and their four continental trades.","ja":"繰り返す署名・作業札・発送地がアレン・セリン・バト・ユアンと四大陸の職務を裏付ける。"}},"next":{"ko":"줄레와 네 사람이 함께 서명한 본문을 대조해 섬의 목적과 마지막 지명을 읽자.","en":"Compare the jointly signed text with Zuleh to establish the isle’s purpose and final place-name.","ja":"ズレと四人が共に署名した本文を照合し、島の目的と最後の地名を読もう。"}},
  {"chapter":17,"stage":"compare","requires":["voyage-17-verify"],"setup":{"ko":"줄레는 햇실도시에서 네 서명과 작업 문양이 모두 들어간 창립 편지 사본을 펼친다. 확인한 네 인물의 이름으로 편지의 목적 조항과 항로 끝의 지명을 읽어 보자.","en":"In Sunloom, Zuleh unfolds a founding-letter copy bearing all four signatures and work emblems. Use the established identities to read its purpose clause and the place-name at the route’s end.","ja":"陽織の街でズレは四つの署名と作業紋の揃う創設の手紙を広げる。確かめた四人の名から目的条項と航路の終わりの地名を読もう。"},"approaches":{"observe":{"ko":"네 서명과 목적 조항 대조하기","en":"Compare four signatures and the purpose clause","ja":"四つの署名と目的条項を比べる"},"analyze":{"ko":"지명과 완성 항로의 끝점 맞추기","en":"Match place-name and route endpoint","ja":"地名と完成航路の終点を合わせる"},"restore":{"ko":"흩어진 창립 편지 본문 잇기","en":"Join the founding-letter text","ja":"分かれた創設の手紙の本文を繋ぐ"}},"success":{"ko":"네 사람은 해전의 약탈을 피해 씨앗·지식·편지를 지킬 공동 피난처를 세우며 그 이름을 새벽너머섬이라 적었다. 별길·바람·나침반·조수와 안개 표지·귀환 절차가 그 지명의 접안 표지로 이어져 항로가 완성됐다.","en":"The four founded a shared refuge for seeds, knowledge and letters against sea-war seizure and named it Beyond-Dawn Isle. Stars, wind, compass, tides, mist signs and return procedures connect to its landing mark, completing the route.","ja":"四人は海戦の略奪から種・知恵・手紙を守る共同避難所を築き、暁の向こうの島と名づけた。星路・風・羅針盤・潮と霧の標・帰還手順がその接岸標に繋がり、航路が完成した。"},"failure":{"ko":"항로 끝 글자를 사람 이름으로 읽어 뜻이 이어지지 않으니 목적 조항과 지명칸을 나누어 다시 읽자.","en":"The route’s final letters were read as a person’s name; separate the purpose clause from the place-name box.","ja":"航路の終わりの字を人名と読んで意味が繋がらないので、目的条項と地名欄を分けて読み直そう。"},"clue":{"name":{"ko":"네 창립자의 뜻과 새벽너머섬 항로","en":"The founders’ purpose and route to Beyond-Dawn Isle","ja":"四人の目的と暁の向こうの島への航路"},"fact":{"ko":"네 창립자의 서명문은 공동 피난처의 목적과 새벽너머섬이라는 이름을 적으며 완성한 항로의 접안 표지에 대응한다.","en":"The four founders’ signed text names the shared refuge Beyond-Dawn Isle and matches the completed route’s landing mark.","ja":"四人の署名文は共同避難所を暁の向こうの島と名づけ、完成航路の接岸標と対応する。"}},"next":{"ko":"호박빛항의 사피와 출항 준비를 마치고 주괴 두 개를 챙겨 새벽너머섬의 실제 표지를 확인하러 가자.","en":"Prepare with Safi in Amberwake Port, bring two ingots, and sail to verify Beyond-Dawn Isle’s actual signs.","ja":"琥珀の港のサフィと支度し、延べ棒を二つ用意して暁の向こうの島の実際の標を確かめに行こう。"}},
  {"chapter":18,"stage":"field","requires":["voyage-17-compare"],"setup":{"ko":"완성한 항로를 따라 닿은 새벽너머섬 해안에서 안개가 네 문양 사이로 갈라진다. 낮은 돌담 너머에는 꽃과 나무가 보이지만, 먼저 육지로 돌아갈 표지가 맞는지 확인해야 한다.","en":"On Beyond-Dawn Isle’s shore, reached along the completed route, mist parts between four emblems. Flowers and trees stand beyond a low wall, but the homeward signs must be checked before proceeding.","ja":"完成した航路で着いた暁の向こうの島の岸で、霧が四つの紋の間から割れる。低い石垣の向こうに花と木が見えるが、まず陸へ戻る標が合うか確かめる必要がある。"},"approaches":{"observe":{"ko":"해안의 네 문양과 출구 살피기","en":"Inspect shore emblems and the exit","ja":"岸の四紋と出口を見る"},"analyze":{"ko":"접안·귀환 방위 교차 대조하기","en":"Cross-check landing and return bearings","ja":"接岸と帰路の方角を突き合わせる"},"restore":{"ko":"해안 판독 표식 맞추기","en":"Align shoreline sight marks","ja":"海岸の読取目印を合わせる"}},"success":{"ko":"네 문양의 길은 실제 정원 입구로 이어지고 귀환 표지는 외해의 육지 쪽 별길과 맞았다. 문서 속 피난처를 조사할 현장과 돌아올 기준점을 함께 확인했다.","en":"The four-emblem path leads to a real garden entrance, and the return signs match the landward starcourse outside the mist. Both the refuge’s physical site and a reference for the way back are now confirmed.","ja":"四紋の道は実際の庭の入口に続き、帰路標は霧の外の陸への星路と合った。文書の避難所を調べる現場と、戻るための基準点を共に確かめた。"},"failure":{"ko":"들어온 표지와 귀환 표지를 같은 방향으로 놓아 기준을 확인하지 못했으니 두 줄의 시작 홈부터 나누자.","en":"Inward and return signs were aligned the same way; distinguish their starting notches before checking the reference.","ja":"往路標と帰路標を同じ向きに置いて基準を確かめられないので、二列の始めの溝から分けよう。"},"clue":{"name":{"ko":"실제 정원과 맞는 귀환 표지","en":"A real garden and matching return signs","ja":"実際の庭と合う帰路標"},"fact":{"ko":"섬의 네 문양 길은 실제 정원으로 이어지며 해안 귀환 표지는 외해의 육지 쪽 별길과 일치한다.","en":"The isle’s four-emblem path reaches a real garden, and its return signs match the landward starcourse in outer waters.","ja":"島の四紋の道は実際の庭へ続き、岸の帰路標は外海の陸への星路と一致する。"}},"next":{"ko":"정원 안 씨앗집의 원본 목록과 편지함을 조사해 창립 기록이 실제로 무엇을 지켰는지 검증하자.","en":"Inspect the seed house’s original catalog and letter box to establish what the founding records protected.","ja":"庭の種の蔵の原目録と手紙箱を調べ、創設記録が実際に何を守ったか確かめよう。"}},
  {"chapter":18,"stage":"verify","requires":["voyage-18-field"],"setup":{"ko":"실제 정원과 귀환 표지를 확인한 뒤 씨앗집의 목록과 봉인 문서를 펼친다. 편지함에는 서로 다른 봉인의 장부와 봉투 꾸러미가 창립 헌장과 따로 묶여 있다.","en":"After confirming the garden and return signs, open the seed catalog and sealed records. The letter box holds ledgers and bundles of envelopes under different seals, separate from the founding charter.","ja":"実際の庭と帰路標を確かめ、種の目録と封印文書を開く。手紙箱には異なる封印の帳簿と封筒の束が、創設憲章とは別に綴じられている。"},"approaches":{"observe":{"ko":"정원 목록과 답장 인장 살피기","en":"Inspect garden lists and reply seals","ja":"庭の目録と返書の印を見る"},"analyze":{"ko":"창립 원본과 말년 기록 교차 대조하기","en":"Cross-check founding and late records","ja":"創設原本と晩年の記録を突き合わせる"},"restore":{"ko":"접힌 헌장과 답장 읽는 순서 맞추기","en":"Arrange the folded charter and replies","ja":"折られた憲章と返書の読む順を整える"}},"success":{"ko":"정본 헌장과 목록은 씨앗·항해 지식·편지를 지키는 공동 정원과 혈통 대신 항법을 살피는 보호 안개를 설명했다. 말년 장부와 서명 답장은 발신자들이 자발적으로 정원을 돌보며 여생을 보냈음을 확인하고, 잃은 꽃과 말의 귀환이라는 기록이 소원 전설의 바탕이었음을 보여 주었다.","en":"The original charter and catalog describe a shared garden preserving seeds, navigation and letters, with a ward testing navigation rather than bloodline. Late ledgers and signed replies establish that the writers voluntarily tended it for the rest of their lives, while accounts of recovered flowers and words explain the wish legend’s source.","ja":"原本の憲章と目録は、種・航海の知恵・手紙を守る共同の庭と、血筋でなく航法を確かめる霧を説明した。晩年の帳簿と署名返書で書き手が自ら庭を守って余生を送ったと分かり、失った花と言葉の帰還が願いの伝説の元だったと示された。"},"failure":{"ko":"답장 인장을 창립 헌장 인장과 혼동해 시기를 잇지 못했으니 발신 표식별로 묶음을 다시 나누자.","en":"A reply seal was confused with the founding seal; regroup the bundles by dispatch mark before joining their periods.","ja":"返書の封印と創設憲章の印を取り違えて時期を結べないので、差出印ごとに束を分け直そう。"},"clue":{"name":{"ko":"공동 정원의 원본과 발신자들의 답장","en":"Shared-garden originals and the writers’ replies","ja":"共同の庭の原本と書き手の返書"},"fact":{"ko":"창립 정본과 말년 장부·서명 답장은 공동 정원의 목적과 편지 발신자들의 자발적인 잔류·여생을 입증한다.","en":"Founding originals, late ledgers and signed replies establish the shared garden’s purpose and the writers’ voluntary stay for the rest of their lives.","ja":"創設原本・晩年の帳簿・署名返書は共同の庭の目的と、書き手が自ら残って余生を送ったことを示す。"}},"next":{"ko":"현지 대조대에서 원본 헌장과 선단 독점장을 맞추고 답장·항로를 공동 보관할 기록으로 정리하자.","en":"At the local comparison desk, check charter against fleet deed and prepare common custody records for replies and route.","ja":"現地の照合台で原本の憲章と船団の独占状を合わせ、返書と航路を共同保管する記録へ整えよう。"}},
  {"chapter":18,"stage":"compare","requires":["voyage-18-verify"],"setup":{"ko":"사피가 출항 전에 준비한 대조 지침에 따라 섬의 작업대에 정본 헌장·서명 답장과 선단 독점장을 나란히 놓는다. 공동 항해일지의 마지막 보고란을 남겨 두고 위조 여부와 함께 보관할 사본을 확정하자.","en":"Following the comparison notes Safi prepared before departure, lay the original charter, signed replies and fleet deed on the isle’s workbench. Leave the journal’s final report open while establishing the forgery and preparing copies for common custody.","ja":"サフィが出航前に用意した照合の手引きに従い、島の作業台へ原本の憲章・署名返書と船団の独占状を並べる。航海日誌の最後の報告欄を空けたまま、偽造の判定と共同保管の写しを整えよう。"},"approaches":{"observe":{"ko":"헌장과 독점장의 서명 대조하기","en":"Compare charter and deed signatures","ja":"憲章と独占状の署名を比べる"},"analyze":{"ko":"공동 조항·필적·인장 교차 검증하기","en":"Cross-check common-use clause, hand and seal","ja":"共同条項・筆跡・印を突き合わせる"},"restore":{"ko":"길드용 인증 사본과 항해일지 엮기","en":"Assemble guild copies and the voyage journal","ja":"ギルド用認証写しと航海日誌を綴じる"}},"success":{"ko":"독점장의 인장과 서명은 정본의 필적·공동 조항에 모순되어 위조임이 확인됐다. 네 대륙 길드용 인증 사본과 안전 항로·귀환길·발신자의 답장을 묶은 일지 초고를 마련해 마지막 현지 보고만 남았다.","en":"The deed’s seal and signatures contradict the original hand and common-use clause, establishing a forgery. Certified copies for four continental guilds and a draft journal containing the safe course, way home and writers’ replies are prepared, leaving only the final local report.","ja":"独占状の印と署名は原本の筆跡・共同条項に矛盾し、偽造と確かめられた。四大陸のギルド用認証写しと、安全な航路・帰路・書き手の返書をまとめた日誌草稿が整い、最後の現地報告だけが残った。"},"failure":{"ko":"인장 비교 사본 한 장의 방향이 달라 결론을 묶지 못했으니 정본의 서명선에 맞춰 다시 대조하자.","en":"One seal copy is rotated and prevents a consistent comparison; realign it to the original signature line.","ja":"印の照合写し一枚の向きが違って結論をまとめられないので、原本の署名線に合わせ直そう。"},"clue":{"name":{"ko":"위조 독점장과 공동 보관용 일지 초고","en":"A forged deed and a common-custody journal draft","ja":"偽造の独占状と共同保管の日誌草稿"},"fact":{"ko":"정본 대조로 독점장의 위조를 확인했으며 인증 사본·안전 항로·귀환길·답장이 공동 일지 초고에 묶였다.","en":"Original comparison establishes the forged deed, and the shared draft contains certified copies, safe route, way home and replies.","ja":"原本照合で独占状の偽造を確認し、認証写し・安全な航路・帰路・返書が共同日誌の草稿に綴じられた。"}},"next":{"ko":"섬에서 주괴 두 개를 갖추고 마지막 보고를 항해일지에 기록해 이 항해의 결말을 확정하자.","en":"With two ingots ready on the isle, record the final report in the voyage journal to conclude this voyage.","ja":"島で延べ棒を二つ用意し、最後の報告を航海日誌へ記して、この航海の結びを確定しよう。"}},
];

export const FANTASY_VOYAGE_LATE_CHAPTERS: FantasyVoyageChapterDetail[] = [
  {"chapter":10,"motivation":{"ko":"리라는 사라진 별길을 검증하되 그 지식을 선단의 전유물로 팔고 싶지 않다.","en":"Lyra wants the lost starcourse verified without selling its knowledge into the fleet’s exclusive ownership.","ja":"リラは失われた星路を確かめたいが、その知恵を船団の専有物として売りたくはない。"},"stakes":{"ko":"섬 자체의 이동을 별의 이동으로 착각하면 앞서 얻은 나침반 보정까지 틀어질 수 있다.","en":"Mistaking the island’s drift for stellar movement would also corrupt the compass correction already recovered.","ja":"島自体の移動を星の動きと取り違えると、得た羅針盤の補正まで狂ってしまう。"}},
  {"chapter":11,"motivation":{"ko":"에바는 보고 싶은 낙원과 실제 해안을 구별해 항해자의 기대가 길을 흐리지 않게 하려 한다.","en":"Eva wants to separate a hoped-for paradise from real shores so expectation does not mislead voyagers.","ja":"エヴァは望む楽園と実際の海岸を分け、期待で航海者が道を誤らないようにしたい。"},"stakes":{"ko":"물빛을 진짜 육지로 읽으면 네 번째 단서를 놓치고 잘못된 해안으로 향할 수 있다.","en":"Mistaking waterlight for land would hide the fourth clue and send a voyage toward a false shore.","ja":"水明かりを陸と読めば第四の手掛かりを見失い、偽の海岸へ向かってしまう。"}},
  {"chapter":12,"motivation":{"ko":"미라는 편지의 약속을 허황된 소문으로 버리지 않으면서도 같은 실패로 다른 항해자를 잃고 싶지 않다.","en":"Mira will not discard the letters’ promises as nonsense, but does not want another voyage lost to the same mistake.","ja":"ミラは手紙の約束を空しい噂と捨てたくないが、同じ失敗で別の航海者を失いたくもない。"},"stakes":{"ko":"네 단서가 있다는 자신감만으로 떠나면 옛 원정처럼 출발점으로 돌아오는 이유를 놓칠 수 있다.","en":"Confidence in four clues alone would repeat the old expedition’s unexplained return to its starting point.","ja":"四つ揃った自信だけで出れば、古い遠征が出発点へ戻った理由を見落とす。"}},
  {"chapter":13,"motivation":{"ko":"시오리는 왕실 문장처럼 보인다는 인상보다 표찰의 실제 출처와 읽는 순서를 믿는다.","en":"Shiori trusts labels’ actual provenance and reading order over their resemblance to royal arms.","ja":"シオリは王家の紋に見える印象より、札の実際の出所と読む順を信じる。"},"stakes":{"ko":"문양의 방향을 틀리게 읽으면 안개 표지를 혈통이나 소유권의 증거로 오해할 수 있다.","en":"Misreading the emblems’ orientation could turn mist signs into a false claim of bloodline or ownership.","ja":"紋の向きを読み違えると、霧の標を血筋や所有の証と誤解しかねない。"}},
  {"chapter":14,"motivation":{"ko":"미르은은 변하는 날씨를 정해진 날짜 하나로 뭉뚱그리지 않고 누구나 읽을 수 있는 출항 조건으로 정리하려 한다.","en":"Mireun wants changing weather described as readable departure conditions, rather than reduced to a single fixed date.","ja":"ミルンは変わる天候を固定日一つで済ませず、誰もが読める出航条件へまとめたい。"},"stakes":{"ko":"안개 표지의 순서를 알아도 나타나는 조건을 잘못 맞추면 통과 창을 읽지 못한다.","en":"Knowing the mist signs’ order is insufficient if their appearance conditions are misread.","ja":"霧の標の順を知っていても、現れる条件を読み違えれば通過の窓を読めない。"}},
  {"chapter":15,"motivation":{"ko":"하린은 발견의 기쁨만큼 귀환도 중요하게 여기며, 들어가는 길만 적힌 항로를 완성으로 여기지 않는다.","en":"Harin values a homeward path as much as discovery and refuses to call an inward-only route complete.","ja":"ハリンは発見と同じほど帰還を大切にし、入る道だけの航路を完成とは呼ばない。"},"stakes":{"ko":"올 때의 순서를 그대로 뒤집으면 달라진 바람과 조수에 맞지 않아 귀환 근거가 사라진다.","en":"Simply reversing the inward sequence ignores changed wind and tide and leaves the return unsupported.","ja":"往路をそのまま逆にすれば、変わった風と潮に合わず帰還の根拠を失う。"}},
  {"chapter":16,"motivation":{"ko":"솔란은 여러 지역이 나눠 보존한 지식과 그 협력을 지키면서 선단의 주장도 증거로 판단하려 한다.","en":"Solan wants to protect distributed knowledge and cooperation while judging even the fleet’s claims by evidence.","ja":"ソランは各地で分けて守った知恵と協力を守り、船団の主張も証拠で判断したい。"},"stakes":{"ko":"미완성 해도가 진본으로 통하거나 인장 하나가 소유권을 대신하면 협력자들의 노력이 독점 문서로 바뀔 수 있다.","en":"An unfinished chart passed as authentic, or a seal mistaken for ownership, could turn shared work into a monopoly deed.","ja":"未完成の海図が真本とされ、印一つが所有権の代わりになれば、協力が独占の文書へ変わってしまう。"}},
  {"chapter":17,"motivation":{"ko":"줄레는 서명이 있다는 이유만으로 권리를 인정하지 않고, 이름·일·의도가 같은 기록을 가리키는지 확인하려 한다.","en":"Zuleh refuses to treat a signature alone as authority and checks whether names, work and intent point to the same record.","ja":"ズレは署名だけで権利を認めず、名と仕事と意図が同じ記録を指すか確かめたい。"},"stakes":{"ko":"창립자의 신원을 잘못 잇거나 지명을 추측하면 독점장을 반박할 근거와 실제 목적지를 모두 잃을 수 있다.","en":"Misjoining founders or guessing the place-name would undermine both the ownership rebuttal and the actual destination.","ja":"創設者を取り違えたり地名を推測したりすれば、独占状への反証も実際の目的地も失ってしまう。"}},
  {"chapter":18,"motivation":{"ko":"사피는 섬을 발견한 한 사람이 독점하지 않게 근거를 남기고, 미라의 편지와 모두의 귀환 약속을 끝까지 확인하려 한다.","en":"Safi wants evidence against a discoverer’s monopoly and a final answer to Mira’s letters and the shared promise of return.","ja":"サフィは発見者一人の独占を防ぐ根拠を残し、ミラの手紙と皆の帰還の約束を最後まで確かめたい。"},"stakes":{"ko":"기록 속 섬과 실제 정원을 잇고 원본·답장·안전 항로를 공동 보관해야 발견이 또 다른 독점으로 끝나지 않는다.","en":"Records must be joined to the actual garden, and originals, replies and a safe course preserved in common custody so discovery does not become another monopoly.","ja":"記録の島と実際の庭を繋ぎ、原本・返書・安全な航路を共同で保管しなければ、発見が別の独占で終わる。"}},
];
